int FindMin(int[] a) {
    int lo = 0, hi = a.Length - 1;          // the minimum is in [lo..hi]
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;       // mid < hi
        if (a[mid] > a[hi]) lo = mid + 1;   // the drop is right of mid
        else hi = mid;                      // [mid..hi] is sorted
    }
    return lo;                              // index of minimum = rotation
}
// FindMin([4, 5, 6, 7, 0, 1, 2]) == 4: rotated by 4

