int FindMinWithDups(int[] a) {             // #154: duplicates allowed
    int lo = 0, hi = a.Length - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] > a[hi]) lo = mid + 1;
        else if (a[mid] < a[hi]) hi = mid;
        else hi--;                         // a[mid] == a[hi]: the minimum is not lost
    }
    return a[lo];
}
